package br.com.marealta.pousada;

import io.javalin.Javalin;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.UUID;

/** Sobe o sistema inteiro num schema próprio do PostgreSQL, que some no fim. */
final class TestSystem implements AutoCloseable {
    private final String schema = "t_" + UUID.randomUUID().toString().replace("-", "");
    private final Javalin app;
    private final String baseUrl;
    private final HttpClient client = HttpClient.newHttpClient();

    private TestSystem(Config config) {
        app = Main.start(config).start(0);
        baseUrl = "http://localhost:" + app.port();
    }

    static boolean databaseAvailable() {
        String url = System.getenv("DB_URL");
        if (url == null) {
            return false;
        }
        try (Connection ignored = DriverManager.getConnection(url, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"))) {
            return true;
        } catch (SQLException e) {
            return false;
        }
    }

    static TestSystem start(boolean testMode, String messageRules) throws SQLException {
        String schema = "t_" + UUID.randomUUID().toString().replace("-", "");
        String url = System.getenv("DB_URL");
        try (Connection c = DriverManager.getConnection(url, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
             Statement s = c.createStatement()) {
            s.execute("CREATE SCHEMA " + schema);
        }
        String separator = url.contains("?") ? "&" : "?";
        Config config = new Config(0, url + separator + "currentSchema=" + schema, System.getenv("DB_USER"),
                System.getenv("DB_PASSWORD"), testMode, messageRules);
        return new TestSystem(config, schema);
    }

    private TestSystem(Config config, String ignored) {
        this(config);
    }

    record Response(int status, String contentType, String body) {
    }

    Response get(String path) throws Exception {
        return send(HttpRequest.newBuilder(URI.create(baseUrl + path)).GET().build());
    }

    Response post(String path, String body) throws Exception {
        return send(HttpRequest.newBuilder(URI.create(baseUrl + path))
                .POST(HttpRequest.BodyPublishers.ofString(body)).build());
    }

    private Response send(HttpRequest request) throws Exception {
        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        return new Response(response.statusCode(), response.headers().firstValue("content-type").orElse(""), response.body());
    }

    @Override
    public void close() throws Exception {
        app.stop();
        String url = System.getenv("DB_URL");
        try (Connection c = DriverManager.getConnection(url, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
             Statement s = c.createStatement()) {
            s.execute("DROP SCHEMA IF EXISTS " + schema + " CASCADE");
        }
    }
}
